var e=[{name:`basic`,label:`Basic Salary`},{name:`hra`,label:`HRA (House Rent Allowance)`},{name:`da`,label:`DA (Dearness Allowance)`},{name:`conveyance`,label:`Conveyance`},{name:`medical`,label:`Medical`},{name:`specialAllowance`,label:`Special Allowance`},{name:`bonus`,label:`Bonus`}],t=[{name:`pf`,label:`PF (Provident Fund)`},{name:`esi`,label:`ESI (Employees State Insurance)`},{name:`professionalTax`,label:`Professional Tax`},{name:`incomeTax`,label:`Income Tax`},{name:`loan`,label:`Loan`},{name:`other`,label:`Other`}],n=[...e,...t].reduce((e,t)=>({...e,[t.name]:t.label}),{}),r=e=>{if(n[e])return n[e];let t=e.replace(/([A-Z])/g,` $1`);return t.charAt(0).toUpperCase()+t.slice(1)};export{e as n,r,t};